import numpy as np
import pandas as pd


def generate_signals(df):
    close = df["close"]
    hh = df["high"].rolling(12).max()
    ll = df["low"].rolling(12).min()
    osc = (100 * (close - ll) / (hh - ll)).where(hh != ll, 50.0).where(hh.notna())
    o = osc.to_numpy()

    pos = np.zeros(len(df), dtype=int)
    state = 0
    for t in range(len(df)):
        if np.isnan(o[t]):
            state = 0
        elif state == 0:
            if o[t] < 12:
                state = 1
        elif state == 1:
            if o[t] > 45:
                state = 0
        pos[t] = state
    return pd.Series(pos, index=df.index)
