import numpy as np
import pandas as pd


def generate_signals(df):
    close = df["close"]
    c = close.to_numpy()
    sma = close.rolling(20).mean().to_numpy()
    above = c > sma
    below = c < sma
    defined = ~np.isnan(sma)
    cross_up = np.zeros(len(c), dtype=bool)
    cross_up[1:] = defined[1:] & defined[:-1] & above[1:] & ~above[:-1]

    pos = np.zeros(len(c), dtype=int)
    state = 0
    entry = 0.0
    for t in range(len(c)):
        if state == 0:
            if cross_up[t]:
                state, entry = 1, c[t]
            elif cross_down[t]:
                state, entry = -1, c[t]
        elif state == 1:
            if c[t] <= entry * (1 - 0.04) or c[t] >= entry * (1 + 0.08):
                state = 0
        elif state == -1:
            if c[t] >= entry * (1 + 0.04) or c[t] <= entry * (1 - 0.08):
                state = 0
        pos[t] = state
    return pd.Series(pos, index=df.index)
